def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]
    my_prev = history[-2][0] if n >= 2 else 'C'

    opp_coops = 0
    my_coops = 0
    my_defects = 0
    for m, o in history:
        if o == 'C':
            opp_coops += 1
        if m == 'C':
            my_coops += 1
        else:
            my_defects += 1
    coop_rate = opp_coops / n

    w = min(10, n)
    recent = history[-w:]
    recent_coops = 0
    for _, o in recent:
        if o == 'C':
            recent_coops += 1
    recent_rate = recent_coops / w

    w5 = min(5, n)
    recent5 = history[-w5:]
    recent5_coops = 0
    for _, o in recent5:
        if o == 'C':
            recent5_coops += 1

    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    mutual_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_def_streak += 1
        else:
            break

    mutual_coop_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'C':
            mutual_coop_streak += 1
        else:
            break

    offers = 0
    if opp_def_streak > 1:
        start = n - opp_def_streak + 1
        for i in range(start, n):
            if history[i][0] == 'C':
                offers += 1

    forgiven = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            forgiven += 1

    if opp_coops == n and forgiven >= 1:
        return 'D'

    if opp_coops == n and my_defects == 0 and n >= 80:
        return 'D'

    if n == 98:
        if coop_rate >= 0.55 and recent5_coops >= 3 and last_opp == 'C' and mutual_def_streak == 0:
            return 'C'
        return 'D'

    if coop_rate < 0.25:
        if recent_rate >= 0.70 and last_opp == 'C':
            return 'C'
        return 'D'

    if coop_rate < 0.50:
        if recent_rate >= 0.85 and last_opp == 'C':
            return 'C'
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if my_prev == 'D' and opp_def_streak <= 2:
            return 'C'
        if opp_def_streak >= 3 and offers < 2:
            return 'C'
        return 'D'

    if last_my == 'D':
        if (
            forgiven >= 2
            and recent_rate >= 0.80
            and recent5_coops >= 4
            and coop_rate > 0.70
            and rng.random() < 0.10
        ):
            return 'D'
        return 'C'

    return 'C'
